def document_text(kind):
 title,sections=PAGES[kind]
 return title+' | ClipBot\nOperator: '+OPERATOR+'\nLast updated: October 15, 2026\nVersion: '+POLICY_VERSION+'\n\n'+'\n\n'.join(h+'\n'+text for h,text in sections)+'\n'

def document_html(kind):
 title,sections=PAGES[kind]
 content=''.join('<section><h2>'+escape(h)+'</h2><p>'+escape(t)+'</p></section>' for h,t in sections)
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(title)+' | ClipBot</title><link rel="stylesheet" href="/css/legal.css"></head><body><main><nav><a href="/">ClipBot</a> · <a href="/terms">Terms</a> · <a href="/privacy">Privacy</a> · <a href="/acceptable-use">Acceptable use</a></nav><h1>'+escape(title)+'</h1><p>Operator: '+escape(OPERATOR)+'</p><p>Last updated: October 15, 2026 · Version '+POLICY_VERSION+'</p><p class="policy-downloads"><a href="/'+kind+'.txt" download>Download text</a> · <a href="/'+kind+'.html" download>Download HTML</a> · <button type="button" data-print-policy>Print / Save PDF</button></p>'+content+'</main><script src="/js/legal-page.js" defer></script><script src="/js/visitor-presence.js" defer></script></body></html>'

def downloadable_html(kind):
 html=document_html(kind)
 css=(Path(__file__).resolve().parents[1]/'frontend/css/legal.css').read_text(encoding='utf-8')
 return html.replace('<link rel="stylesheet" href="/css/legal.css">','<style>'+css+'</style>').replace('<script src="/js/legal-page.js" defer></script>','').replace('<script src="/js/visitor-presence.js" defer></script>','').replace('<button type="button" data-print-policy>Print / Save PDF</button>','Use your browser menu to print or save as PDF.')

def build_legal_router():
 router=APIRouter()
 for kind in PAGES:
  router.add_api_route('/'+kind,(lambda selected:lambda:HTMLResponse(document_html(selected)))(kind),methods=['GET'],response_class=HTMLResponse)
  for extension,response_type in [('txt',PlainTextResponse),('html',HTMLResponse)]:
   def download(selected=kind,ext=extension,typ=response_type):
    return typ(document_text(selected) if ext=='txt' else downloadable_html(selected),headers={'Content-Disposition':'attachment; filename="clipbot-'+selected+'-'+POLICY_VERSION+'.'+ext+'"'})
   # Freeze closure without exposing function defaults as user-selectable query parameters.
   router.add_api_route('/'+kind+'.'+extension,(lambda fn:lambda:fn())(download),methods=['GET'],response_class=response_type)
 @router.get('/third-party-notices')
 def notices():return PlainTextResponse((Path(__file__).resolve().parents[1]/'packaging'/'THIRD-PARTY-NOTICES.txt').read_text(encoding='utf-8'))
 return router
